/* Maps a controller-pak error code to a save status code, records the failing slot when relevant, and returns the status. */ u16 getSaveErrorStatus(u32 pfsError) {
    u16 status;
    u16 status2;

    gSaveSlotIndex = -1U;
    switch (pfsError) {
    case 0:
        gSaveStatus = 0;
        break;
    case 7:
    case 8:
        status = 0x30;
        gSaveStatus = status;
        break;
    case 4:
        status = 0x15;
        gSaveStatus = status;
        break;
    case 11:
        status2 = 0x62;
        gSaveStatus = status2;
        gSaveSlotIndex = gSaveSlot;
        break;
    case 1:
        status = 0x10;
        gSaveStatus = status;
        break;
    case 2:
        status = 0x12;
        gSaveStatus = status;
        break;
    case 3:
    case 6:
    case 10:
        gSaveStatus = (0x20);
        gSaveSlotIndex = gSaveSlot;
        break;
    default:
        status = 0x11;
        gSaveStatus = status;
        break;
    }
    return gSaveStatus;
}
